import{_ as r,C as a,o as l,c as o,ag as t,E as n}from"./chunks/framework.CtWPcAmt.js";const f=JSON.parse('{"title":"Featured Sellers","description":"","frontmatter":{},"headers":[],"relativePath":"sellers/featured-sellers.md","filePath":"sellers/featured-sellers.md","lastUpdated":1786111645000}'),i={name:"sellers/featured-sellers.md"};function h(d,e,g,u,c,p){const s=a("ImagePopup");return l(),o("div",null,[e[0]||(e[0]=t('<h1 id="featured-sellers" tabindex="-1">Featured Sellers <a class="header-anchor" href="#featured-sellers" aria-label="Permalink to &quot;Featured Sellers&quot;">​</a></h1><p>Featured Sellers spotlights a set of sellers on the storefront — an <strong>Our Featured Sellers</strong> showcase — to give strong or promising sellers extra visibility. The admin turns it on and chooses how sellers are selected; the marketplace then fills the showcase automatically.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>What Featured Sellers does</li><li>How the admin enables and tunes it</li><li>How sellers are chosen</li></ul></div><h2 id="enabling-and-tuning" tabindex="-1">Enabling and tuning <a class="header-anchor" href="#enabling-and-tuning" aria-label="Permalink to &quot;Enabling and tuning&quot;">​</a></h2><p>In the admin panel, go to <strong>Configure → Marketplace → Featured Sellers</strong>.</p>',5)),n(s,{src:"/images/featured-sellers/featured-sellers-config.png",alt:"Featured Sellers configuration"}),e[1]||(e[1]=t('<ul><li><strong>Status</strong> — turn the featured showcase on or off.</li><li><strong>Limit Count</strong> — how many sellers to feature (for example, <strong>12</strong>).</li><li><strong>Popularity Criteria</strong> — how featured sellers are ranked and picked: <ul><li><strong>All</strong> — rank by orders, products, rating, and sales together.</li><li><strong>Maximum Orders</strong> — the sellers with the most orders.</li><li><strong>Maximum Products</strong> — the sellers with the largest catalogs.</li><li><strong>Maximum Rating</strong> — the highest-rated sellers (by approved reviews).</li><li><strong>Maximum Sale</strong> — the sellers with the highest sales value.</li></ul></li></ul><p>Save the configuration, and the storefront shows the featured sellers accordingly.</p><div class="warning custom-block"><p class="custom-block-title">Requires &quot;Show Publicly&quot;</p><p>The showcase only appears when <strong>both</strong> this <strong>Status</strong> toggle <strong>and</strong> the sellers&#39; <strong>Show Publicly</strong> setting (<strong>Configure → Marketplace → Sellers → Registration &amp; Visibility</strong>) are enabled. With Show Publicly off, the storefront hides the showcase even if Featured Sellers is on.</p></div><h2 id="how-the-selection-works" tabindex="-1">How the selection works <a class="header-anchor" href="#how-the-selection-works" aria-label="Permalink to &quot;How the selection works&quot;">​</a></h2><p>Featured placement is <strong>earned, not assigned</strong>. The marketplace ranks eligible sellers by your chosen criteria and takes the top <strong>Limit Count</strong>. Only sellers who are <strong>approved</strong>, <strong>not suspended</strong>, have a business name, and belong to the current channel are eligible — so the showcase always reflects real, active sellers.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Because placement rewards performance, the way for a seller to get featured is simply to sell well and earn good reviews — which ties straight back to <a href="/moderation/rating-management">Rating Management</a> and <a href="/sellers/seller-account-health">Seller Account Health</a>.</p></div>',6))])}const w=r(i,[["render",h]]);export{f as __pageData,w as default};
